// ADR-061 Block 1 — lane-aware floor. managed lane => floor only (the unbounded tail — comment
// thread, parent bodies, semantic-search context, attachment TEXT — is pulled on demand via tools,
// Block 2); bare lane (dormant failover) cannot pull tools, so it keeps today's full assembly.
// Fail-safe to bare/full if the flag is unreadable: a managed run is never starved of context, it
// just carries extra tokens it could have pulled. NOTE: input IMAGES stay eager on both lanes in
// Block 1 (vision blocks); image laziness moves to get_attachment in Block 2 so nothing goes blind.
let agent_lane = 'bare';
try { const lr = $('Read Lane (Stage A)').first().json; const v = String((lr && lr.agent_lane) || '').trim().toLowerCase(); if (v === 'managed' || v === 'bare') agent_lane = v; } catch (e) {}
const isManaged = agent_lane === 'managed';
const floorOnly = isManaged;

const ctx = $('Call Assemble Parent Context').first().json;
const ct = ctx.current_task || {};
const chain = ctx.ancestor_chain || [];
const leaves = ctx.linked_doc_leaves || [];

let pages = [];
try { pages = $('Load Agent Rules').first().json.body || []; } catch (e) {}
const allPages = [];
(function flat(arr){ for (const p of (arr||[])) { allPages.push(p); if (p.pages) flat(p.pages); } })(pages);
const globalPage = allPages.find(p => p.id === 'q7wz-44812');
const global_rules = (globalPage && globalPage.content) ? globalPage.content : '';
// ADR-061 Block 1: on the managed lane the global rules (page q7wz-44812) are already baked verbatim
// into the cached agent `system` by Sync Agent Definitions, so folding them per-run is a pure
// duplicate (~3.5k uncached tok/run) — drop them and never flag them "missing". The bare lane has no
// cached system rules, so it still needs (and is health-checked on) the per-run fold.
const global_rules_missing = isManaged ? false : !global_rules;

const OPERATOR_ID = '2521617';
const OPERATOR_NAME = 'Franciszek Nowak';
const wc = $('When Called').first().json || {};
const reviewer_user_id = (wc.reviewer_user_id || OPERATOR_ID).toString().trim();
const caller_username = (wc.caller_username || OPERATOR_NAME);
const triggered_by = wc.triggered_by || 'explicit_command';
const invocation_type = wc.invocation_type || 'explicit';
const triggering_comment_text = (wc.triggering_comment_text || '').toString().trim();
const triggering_comment_id = (wc.triggering_comment_id || '').toString().trim();

const personalPage = allPages.find(p => p.name === ('Instrukcje dla agenta - ' + caller_username));
const person_rules = (personalPage && personalPage.content) ? personalPage.content : '';
const person_rules_missing = !person_rules;

let task_comments = [], additional_context = '', sources_used = [], sources_filtered_out = 0;
try { const sr = $('Call Assemble Task Context').first().json; task_comments = sr.task_comments || []; additional_context = sr.additional_context || ''; sources_used = sr.sources_used || []; sources_filtered_out = sr.sources_filtered_out || 0; } catch(e) {}

let web_findings = '', web_sources = [];
// research retired (Block 8, ADR-053) — web search is in-harness on the managed lane; bare lane is text+image only

let inBlocks = [], inWarnings = [];
try { const ri = $('Call Read Input').first().json; inBlocks = ri.blocks || []; inWarnings = (ri.warnings || []).slice(); } catch(e) {}
const textBlocks = inBlocks.filter(b => b && b.type === 'text').sort((a,b)=>(a.order||0)-(b.order||0));
const imageBlocks = inBlocks.filter(b => b && b.type === 'image').sort((a,b)=>(a.order||0)-(b.order||0));

let context_gather_ok = false;
try { const cg = $('Call Assemble Parent Context').first().json; context_gather_ok = !!(cg && cg.current_task); } catch(e) {}
let workspace_search_ok = false;
try { const ws = $('Call Assemble Task Context').first().json; workspace_search_ok = ws !== null && ws !== undefined && 'task_comments' in ws; } catch(e) {}
let research_ok = false;
research_ok = true;
let read_input_ok = false;
try { const ri2 = $('Call Read Input').first().json; read_input_ok = ri2 !== null && ri2 !== undefined && 'blocks' in ri2; } catch(e) {}

const lines = [];
// FLOOR: global rules (bare lane only — managed has them cached in system), personal prefs (both lanes).
if (global_rules && !isManaged) { lines.push('# Zasady ogólne agenta (obowiązują zawsze)'); lines.push(global_rules); lines.push(''); lines.push('---'); lines.push(''); }
if (person_rules) { lines.push('# Preferencje osoby zlecającej (' + caller_username + ')'); lines.push(person_rules); lines.push(''); lines.push('---'); lines.push(''); }

// FLOOR: the triggering comment — the immediate request.
lines.push('# Wiadomość wywołująca tę akcję');
lines.push('Użytkownik ' + caller_username + ' napisał:');
lines.push('---');
lines.push(triggering_comment_text || '[treść wiadomości niedostępna]');
lines.push('---');
lines.push('');

// FLOOR: impact line (ADR-061 decision #4) — states the task's weight in-context. Echoed from the
// resolved impact custom field; the tier-additive *system* prefix remains deferred (Block 3).
if (ctx.impact) { lines.push('# Waga zadania (impact)'); lines.push(String(ctx.impact)); lines.push(''); }

// TAIL (managed: pulled on demand via tools): comment thread + semantic-search context.
if (task_comments.length && !floorOnly) { lines.push('# Ostatnie komentarze w zadaniu'); for (const c of task_comments) { lines.push((c.author || 'nieznany') + ': ' + (c.text || '')); } lines.push(''); }
if (additional_context && !floorOnly) { lines.push('# Dodatkowy kontekst (wyszukiwanie semantyczne)'); lines.push(additional_context); if (sources_used.length) lines.push('Źródła: ' + sources_used.join(', ')); lines.push(''); }
if (web_findings) { lines.push('# Wyniki researchu w sieci'); lines.push(web_findings); if (web_sources.length) lines.push('Źródła: ' + web_sources.map(function(s){return s.url;}).join(', ')); lines.push(''); }

// FLOOR: task title + description.
lines.push('# Zadanie');
lines.push(ct.name || '(bez nazwy)');
if (ct.description) { lines.push(''); lines.push(ct.description); }
// TAIL (managed: pulled via get_parent_chain): ancestor bodies + linked-doc leaves.
if (chain.length && !floorOnly) {
  lines.push(''); lines.push('# Kontekst nadrzędny (od najogólniejszego do najbliższego)');
  for (const a of chain.slice().reverse()) { lines.push(''); lines.push('## ' + (a.name || '')); if (a.description) lines.push(a.description); }
}
if (leaves.length && !floorOnly) {
  lines.push(''); lines.push('# Szczegółowe wytyczne');
  for (const l of leaves) { lines.push('- ' + (l.name || '')); if (l.content) lines.push(l.content); }
}

// TAIL (managed: pulled via get_attachment): extracted attachment TEXT. Images stay eager (below).
if (textBlocks.length && !floorOnly) {
  lines.push(''); lines.push('# Treść załączników');
  for (const b of textBlocks) { lines.push(''); lines.push(b.md || ''); }
}

let imageOut = [];
if (imageBlocks.length) {
  imageOut = imageBlocks.map(b => ({ ref: b.ref, mime: b.mime, alt: b.alt, source_ref: b.source_ref || '' }));
  lines.push(''); lines.push('# Załączone obrazy');
  lines.push('Do zadania dołączono ' + imageBlocks.length + ' obraz(y) — przeanalizuj je wizualnie (są przekazane modelowi). Aby wstawić ISTNIEJĄCY załączony obraz do odpowiedzi, użyj bloku embed_input z polem ref ustawionym dokładnie na jedną z wartości ref poniżej.');
  imageBlocks.forEach(function(b, idx){ lines.push('- obraz ' + (idx+1) + ': ref="' + (b.source_ref || b.ref) + '"' + (b.alt ? ' (' + b.alt + ')' : '')); });
}

lines.push('');
lines.push('# Format odpowiedzi (OBOWIĄZKOWY)');
lines.push('Zwróć WYŁĄCZNIE tablicę JSON bloków — bez tekstu przed i po, bez ogrodzenia markdown. Każdy element tablicy to jeden z trzech typów bloków:');
lines.push('  { "type": "text", "md": "…treść markdown po polsku…" }');
lines.push('  { "type": "image", "mode": "embed_input", "ref": "<ref z sekcji Załączone obrazy>", "caption": "…", "alt": "…" }');
const hasInputImages = imageBlocks.length > 0;
if (hasInputImages) { lines.push('  { "type": "image", "mode": "generate", "prompt": "…opis nowego obrazu…", "reference_refs": ["<ref z sekcji Załączone obrazy>"], "aspect": "1:1", "caption": "…", "alt": "…" }'); } else { lines.push('  { "type": "image", "mode": "generate", "prompt": "…opis nowego obrazu…", "aspect": "1:1", "caption": "…", "alt": "…" }'); }
lines.push('Zasady: treść umieszczaj w blokach text (markdown: nagłówki, listy, tabele, pogrubienia). Zachowaj miękką strukturę WEWNĄTRZ bloków text, pomijając puste sekcje: "## Wyniki", "## Pytania do zlecającego", "## Decyzje i kompromisy", a na końcu "## Sugestie do procesu". Blok embed_input wstawia ISTNIEJĄCY załączony obraz (ref dokładnie jak w sekcji „Załączone obrazy”). Blok generate tworzy NOWY obraz (wizualizacja/mockup). Bloki renderowane są w kolejności tablicy. Jeśli obrazy nie są potrzebne, zwróć same bloki text. ROZDZIELCZOŚĆ: w bloku generate możesz dodać opcjonalne pole "size":"SZERxWYS" w pikselach (np. "1024x1536" albo "1536x1024") TYLKO gdy użytkownik wyraźnie prosi o konkretną rozdzielczość (np. szeroki baner, wysokie zdjęcie PDP); w przeciwnym razie pomiń "size" i użyj samego "aspect" do określenia kształtu.');
if (hasInputImages) { lines.push('OBRAZ REFERENCYJNY (reference_refs): gdy zadanie polega na wizualizacji REALNEGO produktu widocznego na załączonym zdjęciu, w bloku generate DODAJ pole "reference_refs" z jedną (lub kilkoma) wartością ref dokładnie jak w sekcji „Załączone obrazy”. Wtedy wygenerowany obraz będzie NOWĄ sceną wizualnie wierną prawdziwemu produktowi (kształt, kolor, logo, proporcje), a nie wymyślonemu. Różnica: embed_input wstawia ISTNIEJĄCY załączony obraz bez zmian; generate + reference_refs tworzy NOWY obraz oparty wizualnie na załączonym zdjęciu (inna scena, tło, ujęcie). Używaj reference_refs TYLKO dla wizualizacji konkretnego załączonego produktu; pomiń je przy czysto abstrakcyjnej lub niezwiązanej z produktem grafice.'); }
if (hasInputImages) { lines.push('Przykład: [{"type":"text","md":"## Wyniki Gotowy opis produktu..."},{"type":"image","mode":"generate","prompt":"packshot produktu na marmurowym blacie, studyjne swiatlo","reference_refs":["' + (imageBlocks[0].source_ref || imageBlocks[0].ref) + '"],"aspect":"1:1","caption":"Wizualizacja na bazie zalaczonego zdjecia","alt":"packshot produktu"}]'); } else { lines.push('Przykład: [{"type":"text","md":"## Wyniki Gotowy opis produktu..."},{"type":"image","mode":"generate","prompt":"packshot kosmetyku na bialym tle, studyjne swiatlo","aspect":"1:1","caption":"Propozycja zdjecia glownego","alt":"packshot"}]'); }

const prompt = lines.join('\n');

return [{ json: {
  prompt,
  agent_lane,
  impact: ctx.impact || '',
  modality: imageOut.length > 0 ? 'multimodal_input' : 'text',
  task_type: '',
  clickup_task_id: (ct.id || ''),
  triggered_by,
  invocation_type,
  reviewer_user_id,
  caller_user_id: reviewer_user_id,
  caller_username,
  process_type: ctx.process_type || '',
  assignee_user_id: ctx.assignee_user_id || '',
  creator_user_id: ctx.creator_user_id || '',
  global_rules_missing,
  person_rules_missing,
  context_gather_ok,
  workspace_search_ok,
  research_ok,
  read_input_ok,
  triggering_comment_id,
  web_sources: JSON.stringify(web_sources),
  image_blocks_json: JSON.stringify(imageOut),
  input_warnings_json: JSON.stringify(inWarnings),
  input_warnings_count: inWarnings.length
} }];
